import json

with open('/app/resources/treasury_bulletin_1990_06.json', 'r') as f:
    data = json.load(f)

# Find tables in the document
def find_tables(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}' if path else k
            if k == 'table':
                print(f'Found table at {new_path}')
                print(json.dumps(v, indent=2)[:2000])
                print('---')
            find_tables(v, new_path)
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_tables(item, f'{path}[{i}]')

find_tables(data)
EOF
